  border-bottom: 1px solid #E2E8F0;
}

/* Price & Status */
.price-status-bar {
  display: flex;
  flex-direction: row;
  justify-content: flex-start;
  align-items: flex-start;
  width: 100%;
}

.price-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  align-items: flex-start;
}

.product-detail-page[dir="rtl"] .price-group {
  align-items: flex-start;
  text-align: right;
}

.product-detail-page[dir="ltr"] .price-group {
  align-items: flex-start;
  text-align: left;
}

.price-unit {
  display: flex;
  flex-direction: row;
  align-items: baseline;
  gap: 8px;
}

.riyal-symbol {
  display: inline-flex;
  align-items: baseline;
}

.riyal-svg {
  width: 21px;
  height: 24px;
  display: block;
}

.currency-code {
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-weight: 700;
  font-size: 20px;
  color: #000000;
}

.price-amount {
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 700;
  font-size: 32px;
  line-height: 48px;
  color: #000000;
}

.vat-tag {
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 400;
  font-size: 12px;
  line-height: 18px;
  color: #64748B;
}

.stock-pill {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 700;
  font-size: 14px;
  line-height: 21px;
}

.stock-pill.is-in-stock {
  color: #10B981;
}

.stock-pill.is-out-stock {
  color: #EF4444;
}

.stock-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
