  background: currentColor;
}

/* Bullet Specs */
.bullet-specs-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 100%;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bullet-spec-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  width: 100%;
}

.product-detail-page[dir="rtl"] .bullet-spec-item {
  justify-content: flex-start;
}

.check-circle-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.bullet-spec-text {
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
  color: #000000;
}

.product-detail-page[dir="rtl"] .bullet-spec-text {
  text-align: right;
}

/* Color Picker */
.color-picker-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.product-detail-page[dir="rtl"] .color-picker-block {
  align-items: flex-start;
}

.color-picker-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 700;
  font-size: 14px;
  line-height: 21px;
  color: #000000;
}

.color-swatches-wrap {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
}

.color-swatch-ring {
  box-sizing: border-box;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  padding: 2px;
  border: 2px solid transparent;
  background: transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
}

.color-swatch-ring:hover {
  transform: scale(1.08);
}

.color-swatch-ring.active {
  border-color: #000000;
}

.swatch-circle {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: block;
}

.swatch-circle.is-light {
  border: 1px solid #cbd5e1;
}

/* Attribute Picker */
.attribute-picker-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.attribute-picker-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 700;
  font-size: 14px;
  line-height: 21px;
  color: #000000;
}

.attribute-options-wrap {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.attribute-btn {
  border: 1px solid #E2E8F0;
  border-radius: 8px;
  background: #FFFFFF;
  color: #000000;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-size: 14px;
  font-weight: 500;
  padding: 8px 16px;
  cursor: pointer;
  transition: all 0.2s;
}

.attribute-btn:hover {
  border-color: #000000;
}

.attribute-btn.active {
  border-color: #000000;
  background: #000000;
  color: #FFFFFF;
  font-weight: 700;
}

/* Purchase Actions */
.purchase-actions-bar {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 16px;
  width: 100%;
}

.btn-add-to-cart {
  flex: 1;
  height: 56px;
  background: #000000;
  border: none;
  border-radius: 8px;
  padding: 16px 32px;
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: center;
  gap: 8px;
  color: #FFFFFF;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 700;
  font-size: 16px;
  line-height: 24px;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-add-to-cart:hover:not(:disabled) {
  background: #1F2937;
  transform: translateY(-1px);
}

.btn-add-to-cart:disabled {
  background: #94A3B8;
  cursor: not-allowed;
}

.bag-svg {
  width: 20px;
  height: 20px;
  stroke: #FFFFFF;
}

.qty-control-box {
  box-sizing: border-box;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  gap: 16px;
  width: 104px;
  height: 56px;
  border: 1px solid #E2E8F0;
  border-radius: 8px;
  background: #FFFFFF;
}

.qty-btn {
  background: none;
  border: none;
  padding: 0;
  color: #000000;
  font-size: 20px;
  font-weight: 400;
  cursor: pointer;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
  transition: opacity 0.2s;
}

.qty-btn:hover {
  opacity: 0.6;
}

.qty-val {
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 700;
  font-size: 16px;
  line-height: 24px;
  color: #000000;
  user-select: none;
}

/* 3. Tabs Section */
.tabs-section {
  box-sizing: border-box;
  width: 100%;
  background: #F8FAFC;
  border-top: 1px solid #E2E8F0;
  border-bottom: 1px solid #E2E8F0;
  padding: 48px 0;
  margin-top: 24px;
}

.tabs-header-nav {
  box-sizing: border-box;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 32px;
  width: 100%;
  border-bottom: 1px solid #E2E8F0;
  margin-bottom: 32px;
  padding: 0;
}

.product-detail-page[dir="rtl"] .tabs-header-nav {
  justify-content: flex-start;
}

.tab-nav-btn {
  background: none;
  border: none;
  padding: 0 0 10px 0;
