  transition: all 0.2s;
}

.tab-nav-btn .tab-label {
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
  color: #64748B;
  transition: color 0.2s;
  white-space: nowrap;
}

.tab-nav-btn:hover .tab-label {
  color: #000000;
}

.tab-nav-btn.active .tab-label {
  font-weight: 700;
  color: #000000;
}

.tab-indicator {
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: #000000;
}

/* Tab 1: Overview */
.overview-tab-content {
  width: 100%;
}

.overview-text {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
}

.ov-title {
  margin: 0;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 700;
  font-size: 24px;
  line-height: 36px;
  color: #000000;
}

.product-detail-page[dir="rtl"] .ov-title {
  text-align: right;
}

.ov-desc {
  margin: 0;
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 500;
  font-size: 16px;
  line-height: 24px;
  color: #64748B;
}

.product-detail-page[dir="rtl"] .ov-desc {
  text-align: right;
}

.features-icons-grid {
  display: grid;
