  align-items: center;
  justify-content: center;
}

.feat-txt {
  font-family: 'IBM Plex Sans Arabic', sans-serif;
  font-style: normal;
  font-weight: 400;
  font-size: 14px;
  line-height: 21px;
  color: #64748B;
}

.product-detail-page[dir="rtl"] .feat-txt {
  text-align: right;
}

/* Tab 2: Specs */
.specs-tab-content {
  width: 100%;
}

.specs-card {
  box-sizing: border-box;
  background: #FFFFFF;
  border: 1px solid #E2E8F0;
  border-radius: 12px;
  padding: 24px 32px;
