  width: 100%;
}

.spec-table-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 48px;
  padding: 12px 0;
  border-bottom: 1px solid #E2E8F0;
}

.spec-table-row:last-child {
  border-bottom: none;
}

@media (max-width: 768px) {
